fn test_bound_collection_attr_value_fails_loud() {
	f := tmp_doc('enumattr', '[?let [= \$s [schema [field name="color" enum=["red", "green"]]]]\n  [out [\$s]]]\n')
	defer { os.rm(f) or {} }
	r := os.execute('${cx_bin()} ${f}')
