// ── source: vcx/tests/body_value_test.v ──
// v08_body_value_test — cluster 2 (TYPED-LIST/CONTENT) of the parser-parity
// convergence. Both engines apply §9 [L25a-b] body-value classification: a
// multi-token whitespace body whose every item is a non-bareword scalar is a
// TYPED LIST of discrete items (heterogeneous types preserved, NO auto-array,
// NO int→float promotion — @CHOICE-1 "one layer", slice A); a body with any
// bareword is PROSE (one Text run). Convergence target is cx.parse.

fn cc(src string) string {
	n := code.program_parse_to_typed_node(src) or { return 'REJECT' }
	return code.render_canonical(n)
}

fn xc(src string) string {
	doc := cx.parse(src) or { return 'REJECT: ${err}' }
	if doc.elements.len != 1 {
		return 'REJECT: ${doc.elements.len} elements'
	}
	return code.render_canonical(doc.elements[0])
}

// ── AUTOARRAY ──
fn test_int_array() {
	assert cc('[items 1 2 3]') == '[items 1 2 3]'
	assert cc('[items 1 2 3]') == xc('[items 1 2 3]')
}

fn test_int_float_heterogeneous() {
	// @CHOICE-1 §9-one-layer (slice A): a whitespace scalar run is a TYPED LIST of
	// discrete items — NOT an auto-array. Heterogeneous per-item types are
	// PRESERVED; there is no int→float promotion (the old `[ns 1.0 2.0 3.0]`
	// float[] form is retired). Both engines converge to the heterogeneous list.
	assert cc('[ns 1 2.0 3]') == '[ns 1 2.0 3]'
	assert cc('[ns 1 2.0 3]') == xc('[ns 1 2.0 3]')
}

fn test_bool_array() {
	assert cc('[bs true false true]') == xc('[bs true false true]')
}

fn test_date_array() {
	assert cc('[ds 2024-01-15 2024-02-20]') == '[ds 2024-01-15 2024-02-20]'
	assert cc('[ds 2024-01-15 2024-02-20]') == xc('[ds 2024-01-15 2024-02-20]')
}

// ── CONTENT (prose) ──
fn test_bareword_prose() {
	assert cc('[words alpha beta gamma]') == "[words 'alpha beta gamma']"
	assert cc('[words alpha beta gamma]') == xc('[words alpha beta gamma]')
}

fn test_mixed_string_int_prose() {
	assert cc('[map x 1]') == "[map 'x 1']"
	assert cc('[map x 1]') == xc('[map x 1]')
}

// ── D3: digit-less token is NOT a float ──
fn test_bare_e_is_string() {
	// Regression for cxparse Class-D D3: bare `e` was autotyped to float 0.0
	// by the data parser (strconv.atof64('e') leniently returns 0.0). Lexicon
	// [L20b] Float requires an Integer mantissa, so a digit-less token falls
	// through to Text. cx (data) now matches code (program): a string.
	assert xc('[name e]') == "[name 'e']"
	assert cc('[name e]') == "[name 'e']"
	assert cc('[name e]') == xc('[name e]')
	// the same digit-less class: a lone `E`, `.`, `e+` are all strings, not 0.0
	assert xc('[a E]') == "[a 'E']"
	assert xc('[a e+]') == "[a 'e+']"
	assert xc('[a E]') == cc('[a E]')
}

// ── D4: triple-quoted strings get common-indent strip ──
fn test_triple_quote_dedent() {
	// cxparse Class-D D4: the program lexer delivered triple-quote content
	// verbatim (no dedent), so `[desc '''⏎  hello⏎  world⏎''']` kept the 2-
	// space indent + surrounding blank lines. ast.md §Text + conformance
	// ext-038 require common-indent strip; both parsers now share one impl.
	src := "[desc '''\n  hello\n  world\n''']"
	// I1 L15 (W-12): the dedented value re-emits with the §2.4 \n escape —
	// quoted canonical text carries no raw control bytes (was raw-newline
	// single-quoted pre-epoch; the corpus twin ext-038 re-blesses at I1).
	assert cc(src) == "[desc 'hello\\nworld']"
	assert cc(src) == xc(src)
	// no-indent content is unchanged by the strip
	src2 := "[d '''\nx\n''']"
	assert cc(src2) == xc(src2)
}

// ── D2: leading-zero integer is a string, not an int ──
fn test_leading_zero_is_string() {
	// cxparse Class-D D2: the program path read `[zip 02134]` as int 2134
	// (leading zero dropped). Lexicon [L20c]: a leading-zero plain integer is
	// NOT an Integer → Text, preserving ZIPs / SKUs. cx already does this.
	assert cc('[zip 02134]') == "[zip '02134']"
	assert cc('[zip 02134]') == xc('[zip 02134]')
	assert cc('[code 007]') == "[code '007']"
	assert cc('[code 007]') == xc('[code 007]')
	// the lone `0` (and `-0`) stays an int
	assert cc('[n 0]') == '[n 0]'
	assert cc('[n 0]') == xc('[n 0]')
}

// ── single item unaffected ──
fn test_single_scalar_unchanged() {
	// A single scalar child is NOT auto-arrayed; it renders as the lone
	// scalar (a bareword string renders quoted, the canonical form).
	assert cc('[n 42]') == '[n 42]'
	assert cc('[name Alice]') == "[name 'Alice']"
	assert cc('[name Alice]') == xc('[name Alice]')
}

// ── source: vcx/tests/call_arg_adjacency_test.v ──
// byte-adjacent binding postfix (predicate vs separate arg).
//
// A `[…]` touching a binding/path is a predicate/slice on it; a
// space-separated `[…]` is a separate operand. This is what lets a call
// arg list `[$f $x [g]]` mean "two args" instead of "filter $x by g"
// (the greedy-predicate hazard that broke stdlib hash-031). See
// `lbrack_adjacent_to_prev` in vcx/code/parser.v.

fn parse_ok(src string) cx.Program {
	return cx.parse_program(src) or { panic('parse failed: ${src} — ${err}') }
}

fn test_qualified_call_arg_binding_then_bracket_is_two_args() {
	// `[hash/equals $p@digest [hash/sha384 "hi"]]` — the spaced `[…]` is the
	// SECOND argument, not a predicate on `$p@digest`.
	body := parse_ok('[hash/equals $p@digest [hash/sha384 "hi"]]').body
	if body is cx.ProgramCall {
		assert body.name == 'hash/equals'
		assert body.args.len == 2, 'expected 2 args, got ${body.args.len}'
		a0 := body.args[0]
		if a0 is cx.ProgramBinding {
			assert a0.name == 'p'
			assert a0.path.len == 1
			assert a0.path[0].predicates.len == 0, 'arg0 must not carry a predicate'
		} else {
			assert false, 'arg0 should be a ProgramBinding'
		}
		assert body.args[1] is cx.ProgramCall, 'arg1 should be the [hash/sha384 …] call'
	} else {
		assert false, 'expected ProgramCall'
	}
}

fn test_dollar_call_arg_binding_then_bracket_is_two_args() {
	// Common lambda-call shape `[$myfn $x [g]]` — `[g]` is the second arg.
	body := parse_ok('[$myfn $x [g]]').body
	if body is cx.ProgramCall {
		assert body.name == 'myfn'
		assert body.args.len == 2, 'expected 2 args, got ${body.args.len}'
	} else {
		assert false, 'expected ProgramCall'
	}
}

fn test_adjacent_bracket_stays_predicate() {
	// No space: `$x/item[1]` keeps the `[1]` as a position predicate.
	body := parse_ok('$x/item[1]').body
	if body is cx.ProgramBinding {
		assert body.path.len == 1
		assert body.path[0].name == 'item'
		assert body.path[0].predicates.len == 1, 'adjacent [1] must be a predicate'
	} else {
		assert false, 'expected ProgramBinding'
	}
}

fn test_adjacent_slice_stays_slice() {
	// No space: `$xs[2:5]` stays a slice access on `$xs`.
	body := parse_ok('$xs[2:5]').body
	assert body is cx.ProgramSliceAccess, 'adjacent [2:5] must be a slice access'
}

// ── byte-adjacent path-step harvest (call head vs path) ────────────
//
// Path-step tokens (/, //, @, .) bind to a $binding only when byte-adjacent.
// A spaced step token is a separate operand — so `[$count //*]` parses as a
// call to $count on the `//*` arg, not as the head `$count//*` (which the
// parser rejects as "call head may not carry path steps").

fn test_spaced_pathexpr_is_call_arg_not_head_path() {
	body := parse_ok('[$count //*]').body
	if body is cx.ProgramCall {
		assert body.name == 'count'
		assert body.args.len == 1, 'expected 1 arg (//*), got ${body.args.len}'
		assert body.args[0] is cx.ProgramPathExpr, 'arg should be a //* PathExpr'
	} else {
		assert false, 'expected ProgramCall'
	}
}

fn test_adjacent_path_stays_path() {
	// No space: `$doc/user/name` keeps all three child steps on the binding.
	body := parse_ok('$doc/user/name').body
	if body is cx.ProgramBinding {
		assert body.name == 'doc'
		assert body.path.len == 2, 'expected 2 path steps, got ${body.path.len}'
	} else {
		assert false, 'expected ProgramBinding'
	}
}

// ── qualified-name colon (prefix:local) is not a slice marker ──────
//
// A CXPath nodetest with a namespace prefix (`//svg:circle`) as a call arg
// must not misroute the bracket to slice-literal parsing on its `:`.

fn test_prefixed_nodetest_call_arg_not_slice() {
	body := parse_ok('[$local-name //svg:circle]').body
	if body is cx.ProgramCall {
		assert body.name == 'local-name'
		assert body.args.len == 1, 'expected 1 arg, got ${body.args.len}'
		assert body.args[0] is cx.ProgramPathExpr, 'arg should be a //svg:circle PathExpr'
	} else {
		assert false, 'expected ProgramCall'
	}
}

fn test_slice_literal_still_detected() {
	// The qualified-colon skip must not break real slice literals.
	assert parse_ok('[2:5]').body is cx.ProgramSliceLiteral, '[2:5] must stay a slice literal'
}

// ── [?let] clause-child eval (gap-a fix) ───────────────────────────
//
// `[?let [= $x V] BODY]` must (1) put $x in scope for BODY of any shape — a
// space-separated sequence value like `(1, 2, 3)` must not be eaten as a
// `$x(...)` paren-call (byte-adjacency for `$name(`); and (2) treat the LAST
// positional as the body even when shape-identical to a `[= …]` binding (an
// equality expression).

fn evlet(src string) string {
	prog := cx.parse_program(src) or { return 'PARSE_ERR' }
	mut env := code.new_env()
	r := code.eval(prog.body, mut env) or { return 'EVAL_ERR ' + err.msg() }
	return code.render_node_pub(r)
}

fn test_let_clause_seq_value_binds() {
	// Bug 2: `$xs (1,2,3)` must NOT parse as `$xs(1,2,3)` paren-call.
	assert evlet('[?let [= $xs (1, 2, 3)] $xs]') == '(1, 2, 3)'
}

fn test_let_clause_seq_slice_body() {
	assert evlet('[?let [= $xs (10, 20, 30, 40, 50)] $xs[2:5]]') == '(20, 30, 40, 50)'
}

fn test_let_clause_equality_body() {
	// Bug 1: body `[= $a 5]` is equality, not another binding.
	assert evlet('[?let [= $a 5] [= $a 5]]') == 'true'
	assert evlet('[?let [= $a 5] [= $a 6]]') == 'false'
}

fn test_let_clause_multi_binding() {
	assert evlet('[?let [= $a 1] [= $b 2] [+ $a $b]]') == '3'
}

// ── source: vcx/tests/codepoint_charref_test.v ──
// v08_codepoint_charref_test — D-K (lexicon [L32] CODEPOINT VALIDITY): an XML
// character reference `&#…;` whose decoded value is a UTF-16 surrogate
// (U+D800–U+DFFF) or is > U+10FFFF is REJECTED (cx-err:CXERLEX-CODEPOINT),
// matching the `\u`/`\U` escape rule (already enforced). Valid char-refs still
// resolve to their character.

fn test_charref_hex_surrogate_rejected() {
	if _ := cx.parse('[x &#xD800;]') {
		assert false, 'surrogate char-ref &#xD800; must be rejected'
	}
}

fn test_charref_hex_over_range_rejected() {
	if _ := cx.parse('[x &#x110000;]') {
		assert false, 'over-range char-ref &#x110000; must be rejected'
	}
}

fn test_charref_decimal_surrogate_rejected() {
	// 55296 == 0xD800
	if _ := cx.parse('[x &#55296;]') {
		assert false, 'decimal surrogate char-ref &#55296; must be rejected'
	}
}

fn test_valid_charrefs_still_resolve() {
	doc := cx.parse('[x &#65;]') or { panic('valid &#65; should parse: ${err}') }
	assert doc.elements.len == 1
	doc2 := cx.parse('[x &#x41;]') or { panic('valid &#x41; should parse: ${err}') }
	assert doc2.elements.len == 1
	// U+10FFFF is the highest valid scalar — must be accepted.
	doc3 := cx.parse('[x &#x10FFFF;]') or { panic('U+10FFFF should parse: ${err}') }
	assert doc3.elements.len == 1
}

// ── source: vcx/tests/collection_literals_test.v ──
// Tests for grammar v3.6 collection-literal source
// productions: SequenceLiteral `(a, b, c)`, ArrayLiteral `[a, b, c]`,
// MapLiteral `{k: v}`. Covers:
//   - Parse: each literal at element-body position
//   - AST: correct node kinds populated (SequenceNode / ArrayNode /
//     MapNode) with expected items / entries
//   - ast_bin v6 round-trip: encode + decode through binary.v with the
//     three new tag bytes (0x0F / 0x10 / 0x11)
//   - Canonical CX emit: round-trip text matches the spec/canonical.md
// formatting rules
//   - Disambiguation: today's element form `[name body]` is unaffected;
//     `[1, 2, 3]` / `['a', 'b', 'c']` becomes ArrayLiteral via the depth-0
//     comma marker. A LEADING BARE WORD is reserved for the element head, so
//     a bare-word string array MUST quote its items (`['web', 'api']`, not
//     `[web, api]`) — 3a / lexicon §collections [L83]. `(text)` and `{text}`
//     without separators stay as body text.
// ── ArrayLiteral ─────────────────────────────────────────────────────────────

fn test_array_literal_in_body() {
	doc := cx.parse("[tags ['web', 'api', 'native']]") or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == 'tags'
	assert root.items.len == 1
	arr := root.items[0]
	assert arr is cx.ArrayNode
	an := arr as cx.ArrayNode
	assert an.items.len == 3
}

fn test_array_literal_empty() {
	doc := cx.parse('[tags []]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.items.len == 1
	arr := root.items[0]
	assert arr is cx.ArrayNode
	an := arr as cx.ArrayNode
	assert an.items.len == 0
}

fn test_array_literal_nested_preserves_structure() {
	doc := cx.parse('[grid [[1, 2], [3, 4]]]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	outer := root.items[0]
	assert outer is cx.ArrayNode
	on := outer as cx.ArrayNode
	assert on.items.len == 2
	first := on.items[0]
	assert first is cx.ArrayNode
	fa := first as cx.ArrayNode
	assert fa.items.len == 2
}

fn test_array_literal_trailing_comma() {
	doc := cx.parse("[tags ['a', 'b', 'c',]]") or { panic(err) }
	root := doc.root() or { panic('no root') }
	arr := root.items[0]
	assert arr is cx.ArrayNode
	an := arr as cx.ArrayNode
	assert an.items.len == 3
}

// ── SequenceLiteral ──────────────────────────────────────────────────────────

fn test_sequence_literal_in_body() {
	doc := cx.parse('[result (1, 2, 3)]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	seq := root.items[0]
	assert seq is cx.SequenceNode
	sn := seq as cx.SequenceNode
	assert sn.items.len == 3
}

fn test_sequence_literal_empty() {
	doc := cx.parse('[result ()]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	seq := root.items[0]
	assert seq is cx.SequenceNode
	sn := seq as cx.SequenceNode
	assert sn.items.len == 0
}

fn test_sequence_literal_flattens_on_parse() {
	// CXDM §1.2 sequence-flat principle: nested sequences flatten on
	// construction. ((a, b), c) → (a, b, c).
	doc := cx.parse('[r ((1, 2), 3, (4, 5))]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	seq := root.items[0]
	assert seq is cx.SequenceNode
	sn := seq as cx.SequenceNode
	assert sn.items.len == 5
}

fn test_paren_text_not_a_sequence() {
	// `(text)` without a depth-0 comma stays as body text. This is the
	// pre-v3.6 parens-in-text behaviour and the back-compat path for
	// English prose.
	doc := cx.parse("[note 'see (appendix)']") or { panic(err) }
	root := doc.root() or { panic('no root') }
	// No SequenceNode should appear in items.
	mut has_seq := false
	for item in root.items {
		if item is cx.SequenceNode { has_seq = true }
	}
	assert !has_seq
}

