fn test_ast_bin_v6_array_round_trip() {
	doc := cx.parse("[tags ['web', 'api']]") or { panic(err) }
	bytes := cx.emit_ast_bin(doc)
	// Confirm the version byte was bumped to 6.
	assert bytes.len > 4
	assert bytes[4] == 6
	doc2 := cx.bin_to_doc(bytes) or { panic('decode: ${err}') }
	root := doc2.root() or { panic('no root') }
	arr := root.items[0]
	assert arr is cx.ArrayNode
	an := arr as cx.ArrayNode
	assert an.items.len == 2
}

fn test_ast_bin_v6_sequence_round_trip() {
	doc := cx.parse('[r (1, 2, 3)]') or { panic(err) }
	bytes := cx.emit_ast_bin(doc)
	doc2 := cx.bin_to_doc(bytes) or { panic('decode: ${err}') }
	root := doc2.root() or { panic('no root') }
	seq := root.items[0]
	assert seq is cx.SequenceNode
	sn := seq as cx.SequenceNode
	assert sn.items.len == 3
}

fn test_ast_bin_v6_map_round_trip() {
	doc := cx.parse("[stats {name: 'alice', age: 30}]") or { panic(err) }
	bytes := cx.emit_ast_bin(doc)
	doc2 := cx.bin_to_doc(bytes) or { panic('decode: ${err}') }
	root := doc2.root() or { panic('no root') }
	m := root.items[0]
	assert m is cx.MapNode
	mn := m as cx.MapNode
	assert mn.entries.len == 2
	// Second entry is an int-valued ScalarNode.
	age := mn.entries[1]
	assert age.key_type == .string_type
	v := age.value
	assert v is cx.ScalarNode
}

// ── Canonical CX emit ────────────────────────────────────────────────────────

fn test_canonical_emit_array() {
	doc := cx.parse("[tags ['web', 'api']]") or { panic(err) }
	out := cx.emit_cx(doc)
	// Canonical form: `['item', 'item']` with single space after comma.
	// Bare-name string items are QUOTED in array-literal position (3a /
	// lexicon §collections [L83]) so they re-parse — an unquoted leading
	// bareword would re-open the element-head disambiguation. Embedded
	// inside an element body, the array renders inline.
	assert out.contains("['web', 'api']")
}

fn test_canonical_emit_sequence() {
	doc := cx.parse('[r (1, 2, 3)]') or { panic(err) }
	out := cx.emit_cx(doc)
	assert out.contains('(1, 2, 3)')
}

fn test_canonical_emit_map() {
	doc := cx.parse("[stats {name: 'alice', age: 30}]") or { panic(err) }
	out := cx.emit_cx(doc)
	// `name` is a bare-name string → emitted without quotes per
	// emitter_cx.cx_emit_map_key. `'alice'` round-trips through
	// cx_quote_text_if_needed; the value is a string so quotes are
	// chosen when needed.
	assert out.contains('name:')
	assert out.contains('age: 30')
}

// ── Disambiguation regression guards ─────────────────────────────────────────

fn test_existing_element_still_parses() {
	// Pre-v3.6 element form: no commas at depth 0 inside the bracket.
	// Must continue to parse as Element, not ArrayLiteral.
	doc := cx.parse('[server host=localhost port=8080]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == 'server'
	assert root.attrs.len == 2
}

fn test_existing_element_with_body_still_parses() {
	doc := cx.parse('[greeting Hello world]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == 'greeting'
}

// ── Data-shape JSON / YAML / TOML / MD emit ──────────────────

fn test_semantic_json_array() {
	doc := cx.parse("[tags ['web', 'api', 'native']]") or { panic(err) }
	out := cx.emit_semantic_json(doc)
	assert out.contains('"tags"'), 'expected key "tags"; got: ${out}'
	assert out.contains('"web"') && out.contains('"api"') && out.contains('"native"')
	assert out.contains('['), 'expected JSON array; got: ${out}'
}

fn test_semantic_json_sequence_flattens() {
	// SequenceNode emits as a JSON array (parser already flattened per §D12).
	doc := cx.parse('[r ((1, 2), 3)]') or { panic(err) }
	out := cx.emit_semantic_json(doc)
	assert out.contains('1') && out.contains('2') && out.contains('3')
	assert out.contains('[')
}

fn test_semantic_json_map() {
	doc := cx.parse("[stats {region: 'us-west', servers: 12}]") or { panic(err) }
	out := cx.emit_semantic_json(doc)
	assert out.contains('"region"')
	assert out.contains('"us-west"')
	assert out.contains('"servers"')
	assert out.contains('12')
}

fn test_semantic_json_nested_array() {
	doc := cx.parse('[grid [[1, 2], [3, 4]]]') or { panic(err) }
	out := cx.emit_semantic_json(doc)
	// Nesting preserved per §D12.
	assert out.contains('[')
	assert out.contains('1') && out.contains('4')
}

fn test_yaml_array_block_sequence() {
	doc := cx.parse("[tags ['web', 'api']]") or { panic(err) }
	out := cx.emit_yaml(doc)
	// YAML block sequence under the `tags` key.
	assert out.contains('tags:')
	assert out.contains('- web') || out.contains('- "web"')
	assert out.contains('- api') || out.contains('- "api"')
}

fn test_yaml_map_block_mapping() {
	doc := cx.parse("[stats {region: 'us-west', servers: 12}]") or { panic(err) }
	out := cx.emit_yaml(doc)
	assert out.contains('stats:')
	// yaml_str quotes identifiers containing 'e' (float-disambiguation),
	// so the keys land as `"region":` / `"servers":`.
	assert out.contains('region') && out.contains('us-west')
	assert out.contains('servers') && out.contains('12')
}

fn test_toml_array_inline() {
	doc := cx.parse("[cfg tags=['web', 'api']]") or { return }
	out := cx.emit_toml(doc)
	// Sanity — emit doesn't crash on collection-literal content.
	_ = out
}

fn test_toml_map_inline() {
	doc := cx.parse("[doc [stats {region: 'us-west', servers: 12}]]") or { panic(err) }
	out := cx.emit_toml(doc)
	assert out.contains('region') && out.contains('servers')
}

// ── source: vcx/tests/comma_array_test.v ──
// v08_comma_array_test — lexicon.ebnf §9 [L25c] comma-separated element bodies
// in cx.parse. A TOP-LEVEL comma in an unannotated, child-free body is the
// universal list signal: it produces a single ARRAY node holding the items
// (each auto-typed per [L25a]). This is the "cx flavor" rule.
//
// @CHOICE-1 §9-ONE-LAYER (slice B): a comma body is ALWAYS a nested Array node
// — NOT a `T[]`-typed flat body, and NOT int→float promoted. Canonical render
// is therefore the uniform nested array literal `[name [item, item, …]]`, which
// is DISTINCT from a whitespace typed list (`[name a b]` → discrete children)
// and from an explicit `[name::T[] …]` (a `T[]`-typed element). String items
// inside the literal are always quoted (3a) so they round-trip as strings; all
// forms are idempotent through cx.parse (bijection).

fn canon(src string) string {
	doc := cx.parse(src) or { return 'REJECT: ${err}' }
	if doc.elements.len != 1 {
		return 'REJECT: ${doc.elements.len} top-level elements'
	}
	return code.render_canonical(doc.elements[0])
}

// ── comma body → nested array literal (uniform across item types) ──────────

fn test_comma_string_array() {
	// Without commas this is prose ("web prod"); the comma makes it an array.
	assert canon('[tags web, prod]') == "[tags ['web', 'prod']]", canon('[tags web, prod]')
	assert canon('[tags web, prod, us-east]') == "[tags ['web', 'prod', 'us-east']]", canon('[tags web, prod, us-east]')
}

fn test_comma_int_array() {
	assert canon('[ports 80, 443]') == '[ports [80, 443]]', canon('[ports 80, 443]')
}

fn test_comma_float_array() {
	assert canon('[ratios 1.0, 2.5]') == '[ratios [1.0, 2.5]]', canon('[ratios 1.0, 2.5]')
}

fn test_comma_no_promotion() {
	// Heterogeneous per-item types are PRESERVED — no int→float promotion
	// (the old `[xs 1.0 2.0 3.0]` float[] form is retired).
	assert canon('[xs 1, 2.0, 3]') == '[xs [1, 2.0, 3]]', canon('[xs 1, 2.0, 3]')
}

// ── trailing-comma singleton: a 1-item comma array ─────────────────────────

fn test_trailing_comma_singleton() {
	assert canon('[xs a,]') == "[xs ['a']]", canon('[xs a,]')
	// No comma → scalar, NOT a 1-array.
	assert canon('[xs a]') == "[xs 'a']", canon('[xs a]')
}

// ── comma inside quotes is literal; string items always quoted ─────────────

fn test_quoted_comma_literal() {
	// "a, b" contains a comma → it stays one quoted item inside the literal.
	assert canon("[xs 'a, b', c]") == "[xs ['a, b', 'c']]", canon("[xs 'a, b', c]")
}

fn test_string_item_quote_when_autotypes() {
	// A quoted "80" must stay quoted inside the literal or it would re-parse as
	// an int (3a / bijection). `prod` is a bare-name string → also quoted.
	assert canon("[xs '80', prod]") == "[xs ['80', 'prod']]", canon("[xs '80', prod]")
	// Unquoted 80 is genuinely an int; the mixed array keeps it bare, `prod`
	// quoted as a string item.
	assert canon('[xs 80, prod]') == "[xs [80, 'prod']]", canon('[xs 80, prod]')
}

// ── heterogeneous mix → nested array literal ───────────────────────────────

fn test_comma_mixed_array() {
	got := canon('[row 1, two, true]')
	// `1`/`true` stay bare (typed scalars); the bare-name string `two` is quoted.
	assert got == "[row [1, 'two', true]]", got
}

// ── negative controls: no top-level comma → not a comma array ──────────────

fn test_no_comma_unchanged() {
	// whitespace scalar run → typed list of discrete children (slice A).
	assert canon('[items 1 2 3]') == '[items 1 2 3]', canon('[items 1 2 3]')
	// whitespace words → prose ([L25b]).
	assert canon('[words a b c]') == "[words 'a b c']", canon('[words a b c]')
	// comma inside a sequence literal is NOT a top-level body comma.
	assert canon('[pair (1, 2)]') == '[pair (1, 2)]', canon('[pair (1, 2)]')
}

// ── bijection: render is idempotent (re-parse → re-render stable) ──────────

fn test_comma_array_round_trip() {
	srcs := ['[tags web, prod]', '[ports 80, 443]', '[xs a,]', "[xs 'a, b', c]",
		'[row 1, two, true]', '[ratios 1.0, 2.5]', "[xs '80', prod]"]
	for s in srcs {
		once := canon(s)
		twice := canon(once)
		assert once == twice, '${s}: not idempotent: `${once}` → `${twice}`'
	}
}

// ── source: vcx/tests/comment_bracket_balance_test.v ──
// comment_bracket_balance_test.v — the `[; … ]` block comment must balance
// nested `[`…`]` and treat its body as OPAQUE prose under BOTH readings (data ⊂
// program). Regression for the comment-syntax migration: the program lexer and
// the module-loader directive scanner originally closed a `[; … ]` comment at
// the FIRST `]` (and the module scanner quote-shielded apostrophes), so a
// comment whose prose contained brackets — `[; A [bus] owns … ]` — or an
// apostrophe — `[; the draft's note ]` — closed early and corrupted the parse.
// The data reader's read_until_close already balanced; these assert the program
// reader now agrees.
// ── program reader: a bracketed comment body is balanced, not closed early ───

fn test_program_comment_with_inner_brackets() {
	// If the comment closed at the first `]` (after `[x]`), the `2]` would be
	// stranded and `[+ 1 …]` would not evaluate to 3.
	out := cx.parse_program('[+ 1 [; note: the [x] form and [y] ] 2]') or {
		assert false, 'program with bracketed comment failed to parse: ${err}'
		return
	}
	assert out.body is cx.ProgramLiteral || true // parsed; structure asserted via eval elsewhere
}

fn test_program_comment_with_apostrophe_and_brackets() {
	// Apostrophe in prose must not open a string span; brackets must balance.
	src := "[+ 10 [; the draft's [ok]/[err] railway — see §3 ] 20]"
	if _ := cx.parse_program(src) {
		// parsed cleanly
	} else {
		assert false, 'program with apostrophe+bracket comment failed: ${err}'
	}
}

fn test_program_comment_unterminated_still_errors() {
	// A genuinely unterminated comment (no closing `]`) must still error.
	if _ := cx.parse_program('[+ 1 [; never closed 2') {
		assert false, 'unterminated [; comment should not parse'
	}
}

// ── data reader: same comment shapes parse (and agree with the program read) ─

fn test_data_comment_with_inner_brackets() {
	doc := cx.parse('[cfg [; note [a] and [b] ] host=x]') or {
		assert false, 'data doc with bracketed comment failed to parse: ${err}'
		return
	}
	assert doc.elements.len == 1, 'expected one element root, got ${doc.elements.len}'
}

// ── module-loader directive scan: a header comment with brackets + apostrophe
// must not derail directive discovery (this is the exact shape that broke
// stdlib/fp.cx — "the draft's" + "[ok]/[err]"). We assert the [?def] AFTER such
// a comment is still discovered by parsing a module-shaped source as a program.

fn test_module_shaped_source_after_bracketed_comment() {
	src := "[; cx-stdlib/x — the draft's [ok]/[err] protocol; see [?pipe] (§1) ]\n" +
		'[?def f scope=public pure [returns int] (\$x::int) [\$x]]\n'
	if _ := cx.parse_program(src) {
		// the [?def] after the bracketed/apostrophe comment is reachable
	} else {
		assert false, 'module-shaped source after bracketed comment failed: ${err}'
	}
}

// ── #312 hazard semantics (the EBNF now spec's the balanced rule; these pin
// the two documented hazards so the spec text and the engine can't drift):
// a lone '[' in comment prose swallows to EOF → the comment never terminates
// and the parse FAILS (never a silent partial parse).

fn test_lone_open_bracket_in_comment_is_unterminated() {
	src := '[; press the [ key to start ]\n[?def f scope=public pure [returns int] () [1]]\n'
	if _ := cx.parse_program(src) {
		assert false, 'lone [ in comment prose must leave the comment unterminated (parse error)'
	} else {
		// expected: unterminated comment surfaces as a parse error
	}
}

// a lone ']' ends the comment at depth zero — the comment VALUE stops there,
// and what follows must be valid on its own (here it is, so the parse holds
// and the trailing form is real code, not comment prose).

fn test_lone_close_bracket_ends_comment_at_depth_zero() {
	src := '[;short] [p text]'
	doc := cx.parse(src) or {
		assert false, 'comment closed at depth-zero ] must leave a valid parse: ${err}'
		return
	}
	assert doc.elements.len == 1, 'the form after the early-closed comment is CODE, got ${doc.elements.len} roots'
	root := doc.elements[0]
	assert root is cx.Element, 'expected an element root after the early-closed comment'
	assert (root as cx.Element).name == 'p'
}

// ── source: vcx/tests/escape_eof_test.v ──
// LR-ESCAPE (formal lexicon): a quoted body string left unterminated *because*
// a backslash escape consumed the would-be closing quote (`'ab\']`) — or a
// dangling `\` at EOF — is the CXERLEX-ESCAPE lexical fault, distinct from a
// plain unterminated string (`'abc]`), which is NOT retagged.

fn parse_msg(src string) string {
	cx.parse(src) or { return err.msg() }
	return '<accepted>'
}

fn test_escaped_closer_is_escape_error() {
	// `[s 'ab\']` — the `\'` escapes the quote that would have closed the string.
	msg := parse_msg("[s 'ab\\']")
	assert msg.contains('CXERLEX-ESCAPE'), 'want CXERLEX-ESCAPE, got: ${msg}'
}

fn test_plain_unterminated_is_not_retagged() {
	// `[s 'abc]` — plain unterminated, no escape involved → NOT CXERLEX-ESCAPE.
	msg := parse_msg("[s 'abc]")
	assert msg.contains('unterminated'), 'want an unterminated error, got: ${msg}'
	assert !msg.contains('CXERLEX-ESCAPE'), 'plain unterminated must not be CXERLEX-ESCAPE: ${msg}'
}

fn test_valid_escaped_quote_still_parses() {
	// `[s 'a\'b']` — an escaped quote mid-string is content; the string closes
	// normally and parses cleanly.
	cx.parse("[s 'a\\'b']") or { assert false, 'should parse: ${err.msg()}' }
}

// ── source: vcx/tests/head_typeann_test.v ──
// v08_head_typeann_test — cluster 3 (TYPE-ANN) of the parser-parity
// convergence. The PROGRAM parser must accept a glued head TypeAnnotation
// `::T` / `::T[]` / `::[]` (lexicon §7 [L50], §9 [L25d]); code.parse used to
// REJECT it. The annotation OVERRIDES §9 auto-typing. Convergence target is
// cx.parse; both render identically through code.render_canonical.

fn test_scalar_sized_int() {
	assert cc('[port::u16 8080]') == '[port::u16 8080]'
	assert cc('[port::u16 8080]') == xc('[port::u16 8080]')
}

fn test_scalar_int() {
	assert cc('[count::int 5]') == '[count::int 5]'
	assert cc('[count::int 5]') == xc('[count::int 5]')
}

fn test_typed_int_array() {
	// A typed array KEEPS its `::T[]` head and whitespace-separated items —
	// lossless + idempotent. (The old "drop annotation" form was neither: a
	// whitespace body `[xs 1 2 3]` re-parses to discrete children, not an array.)
	assert cc('[xs::int[] 1 2 3]') == '[xs::int[] 1 2 3]'
	assert cc('[xs::int[] 1 2 3]') == xc('[xs::int[] 1 2 3]')
}

fn test_typed_string_array() {
	// Typed string array keeps `::string[]`; bare-eligible items stay bare (the
	// annotation pins the type) and match the cx-module data emitter.
	assert cc('[tags::string[] admin user]') == '[tags::string[] admin user]'
	assert cc('[tags::string[] admin user]') == xc('[tags::string[] admin user]')
}

fn test_inferred_array() {
	// @CHOICE-1 §9-one-layer (slice C): `::[]` KEEPS its `[]` marker and per-item
	// types (heterogeneous, no promotion) — distinct from a whitespace typed list
	// `[xs 1 2 3]` and from an explicit `::T[]`. The annotation is retained on
	// render (it carries the array-vs-mixed-content distinction).
	assert cc('[xs::[] 1 2 3]') == '[xs::[] 1 2 3]'
	assert cc('[xs::[] 1 2 3]') == xc('[xs::[] 1 2 3]')
	// heterogeneous: int + float preserved, no promotion.
	assert cc('[ns::[] 1 2.0 3]') == '[ns::[] 1 2.0 3]'
	assert cc('[ns::[] 1 2.0 3]') == xc('[ns::[] 1 2.0 3]')
}

fn test_unknown_type_tag_rejected() {
	// An unknown tag is a parse error, not a silently-accepted bogus type.
	if _ := code.program_parse_to_typed_node('[x::bogus 1]') {
		assert false, 'expected reject for ::bogus'
	}
}

// ── source: vcx/tests/line_comments_test.v ──
// Tests for v3.4 line comments (# to end-of-line). Spec:
// spec/grammar.ebnf [30b], spec/policies.md.
// ── Top-level line comments ──────────────────────────────────────────────────

fn test_line_comment_before_element() {
	src := '# this is a config
[server host=localhost]'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == 'server'
	assert root.attr('host') == 'localhost'
}

fn test_multiple_line_comments_before_element() {
	src := '# line one
# line two
# line three
[server host=localhost]'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == 'server'
}

fn test_line_comment_terminated_by_eof() {
	src := '[server host=localhost]
# trailing comment with no newline'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == 'server'
}

fn test_line_comment_between_top_level_elements() {
	src := '[a]
# comment between
[b]'
	doc := cx.parse(src) or { panic(err) }
	// A line comment between root nodes is now PRESERVED as a CommentNode
	// sibling (lossless `cx fmt` — canonical.md §2.1), so elements holds
	// [Element a, CommentNode, Element b]. The two real elements are still
	// present; the comment rides between them in document order.
	mut element_count := 0
	for n in doc.elements {
		if n is cx.Element {
			element_count++
		}
	}
	assert element_count == 2
	assert cx.emit_cx(doc).contains('# comment between')
}

// ── Line comments inside element body ────────────────────────────────────────

fn test_line_comment_inside_body() {
	src := '[server
  # web frontend
  host=localhost
  port=8080
]'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.attr('host') == 'localhost'
	assert root.attr('port') == '8080'
}

