// ── source: vcx/tests/module_scan_string_literal_test.v ──
// module_scan_string_literal_test.v — issue #260: the module pre-scan
// (module_loader_scan_directives, the pass the §1.2 exports gate shares)
// must agree with the real lexer about string literals. A lone `[` or `]`
// inside a quoted string must not shift bracket balance — historically a
// def body containing "[err " swallowed every later [?def], so pkg-verify
// raised CXER4884 for defs that plainly exist.

// The directive struct's fields are module-private; the defect (#260) is a
// COUNT defect — a string literal swallowing brackets makes every later
// [?def] vanish from the scan — so counting recognised directives is the
// full assertion. Each source below contains exactly two defs.
fn scan_count(src string) int {
	directives := code.module_loader_scan_directives(src) or { return -1 }
	return directives.len
}

fn test_lone_open_bracket_in_double_quoted_string() {
	src := '[?def is-err (\$x) [\$s:starts-with [\$cx:emit \$x] "[err "]]\n' +
		'[?def readout scope=public impure (\$store \$t) [\$concat "" \$t]]\n'
	assert scan_count(src) == 2
}

fn test_lone_open_bracket_in_single_quoted_string() {
	src := "[?def pfx (\$_) '[err ']\n[?def second (\$_) 1]\n"
	assert scan_count(src) == 2
}

fn test_lone_close_bracket_in_string() {
	src := '[?def sfx (\$_) "] tail"]\n[?def third (\$_) 2]\n'
	assert scan_count(src) == 2
}

fn test_escaped_quote_inside_string() {
	src := '[?def esc (\$_) "a \\" [ b"]\n[?def fourth (\$_) 3]\n'
	assert scan_count(src) == 2
}

// ── source: vcx/tests/qname_attrtype_test.v ──
// v08_qname_attrtype_test — cluster 4 (NAMESPACE + ATTR-TYPE) of the
// parser-parity convergence. The PROGRAM parser must:
//   • fold a byte-adjacent `prefix:local` QName element HEAD ([L11]/[7a]),
//     not read `:local` as an atom child;
//   • auto-type a BARE attribute value via the [L25a] scalar priority — in
//     particular `nil=null` → NullValue, not the string "null".
// Convergence target is cx.parse; both render identically through
// code.render_canonical.

// ── D1: a colon inside a BARE attribute value must NOT split into an atom ──
fn test_bare_attr_value_with_colon() {
	// cxparse Class-D D1: the program parser read `xmlns=urn:example` as
	// attr xmlns="urn" + a stray `:example` atom body item. Lexicon §10
	// [L70] BareValue admits `:`, so the whole `urn:example` is one string.
	// canonical render keeps the value bare (`:` is bare-safe in an attr value)
	// — the point is ONE attribute, no stray `:example` atom body item.
	assert cc('[doc xmlns=urn:example]') == '[doc xmlns=urn:example]'
	assert cc('[doc xmlns=urn:example]') == xc('[doc xmlns=urn:example]')
	// multi-attr line (ns-012 shape) and a multi-segment QName-style value
	assert cc('[item xmlns=urn:foo name=widget count=3]') == xc('[item xmlns=urn:foo name=widget count=3]')
	assert cc('[a v=x:y:z]') == '[a v=x:y:z]'
	assert cc('[a v=x:y:z]') == xc('[a v=x:y:z]')
}

// ── NAMESPACE ──
fn test_qname_head_bare() {
	assert cc('[svg:rect]') == '[svg:rect]'
	assert cc('[svg:rect]') == xc('[svg:rect]')
}

fn test_qname_head_with_attr() {
	assert cc('[svg:rect x=1]') == '[svg:rect x=1]'
	assert cc('[svg:rect x=1]') == xc('[svg:rect x=1]')
}

fn test_qname_head_with_child_prose() {
	// Body `child` is a bareword → prose string (matches cx).
	assert cc('[prefix:local child]') == xc('[prefix:local child]')
}

fn test_plain_atom_child_still_atom() {
	// A SPACE-separated `:rect` is still an atom child, not a qualifier.
	assert cc('[svg :rect]') == '[svg :rect]'
}

// ── ATTR-TYPE ──
fn test_attr_null_autotypes() {
	assert cc('[u nil=null]') == '[u nil=null]'
	assert cc('[u nil=null]') == xc('[u nil=null]')
}

fn test_attr_string_unaffected() {
	// A plain bareword attr value stays a string.
	assert cc('[u name=pizza]') == xc('[u name=pizza]')
}

// ── source: vcx/tests/str_expr_holes_test.v ──
// str_expr_holes_test.v — #66: [?str] interpolation holes accept FULL
// expressions (arithmetic, calls, …), not just binding-paths. Computed holes
// previously silently data-fell-back; now they evaluate, and a non-scalar /
// empty / malformed hole fails loud (no data echo).

fn cx_bin_se() string {
	return testenv.cx_bin()
}

fn run_se(src string) os.Result {
	f := os.join_path(os.temp_dir(), 'cx_se_${os.getpid()}_${src.len}.cx')
	os.write_file(f, src) or { panic('write: ${err}') }
	defer { os.rm(f) or {} }
	return os.execute('${cx_bin_se()} --allow-all ${f}')
}

fn test_arithmetic_hole() {
	r := run_se('[?let [= \$a 2] [= \$b 3] [?str "sum={[+ \$a \$b]}"]]')
	assert r.exit_code == 0, 'errored: ${r.output}'
	assert r.output.trim_space() == "'sum=5'", 'arith hole wrong: ${r.output}'
}

fn test_call_hole() {
	r := run_se("[?lib 'cx-stdlib/strings'] [?let [= \$s \"hi\"] [?str \"up={[\$strings:upper \$s]}\"]]")
	assert r.exit_code == 0, 'errored: ${r.output}'
	assert r.output.trim_space() == "'up=HI'", 'call hole wrong: ${r.output}'
}

fn test_mixed_binding_and_computed_holes() {
	r := run_se('[?let [= \$a 2] [?str "a={\$a} double={[* \$a 2]}"]]')
	assert r.exit_code == 0, 'errored: ${r.output}'
	assert r.output.trim_space() == "'a=2 double=4'", 'mixed holes wrong: ${r.output}'
}

fn test_binding_path_hole_still_works() {
	r := run_se('[?let [= \$u [user name=Alice]] [?str "name={\$u@name}"]]')
	assert r.exit_code == 0, 'errored: ${r.output}'
	assert r.output.trim_space() == "'name=Alice'", 'path hole regressed: ${r.output}'
}

fn test_non_scalar_hole_fails_loud() {
	// a hole resolving to a sequence is a CXER0100 at eval — NOT a silent data
	// echo of the program.
	r := run_se('[?str "x={(1,2,3)}"]')
	assert r.exit_code != 0, 'non-scalar hole should fail loud: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected CXER0100: ${r.output}'
	// exit!=0 above already proves fail-loud (a silent data echo would exit 0).
}

fn test_empty_hole_fails_loud() {
	r := run_se('[?str "x={}"]')
	assert r.exit_code != 0, 'empty hole should fail loud: ${r.output}'
	assert r.output.contains('CXER0100'), 'expected CXER0100: ${r.output}'
	// exit!=0 above already proves fail-loud (a silent data echo would exit 0).
}

// ── source: vcx/tests/str_raw_literal_test.v ──
// str_raw_literal_test.v — #93 (literal piece): the `r'''…'''` / `r"""…"""`
// RAW triple-quoted string preserves its content VERBATIM (no common-indent
// dedent), so leading-whitespace-significant blocks (indented code, tab-aligned
// text) survive byte-exact — the authoring half of in-CX surgical edits. Plain
// `'''…'''` keeps its dedent; a bare `r` stays an ordinary identifier.

fn cx_bin_rl() string {
	return testenv.cx_bin()
}

fn run_rl(src string) os.Result {
	f := os.join_path(os.temp_dir(), 'cx_rl_${os.getpid()}_${src.len}.cx')
	os.write_file(f, src) or { panic('write: ${err}') }
	defer { os.rm(f) or {} }
	return os.execute('${cx_bin_rl()} ${f}')
}

fn test_raw_preserves_leading_indent() {
	// r''' → no dedent: the two leading tabs on each content line survive in
	// the VALUE. I1 L15 (W-12): the rendered spelling shows them as §2.4
	// `\t` escapes — quoted output never carries raw control bytes.
	r := run_rl("[?str r'''\n\t\tA\n\t\tB''']")
	assert r.exit_code == 0, 'errored: ${r.output}'
	assert r.output.contains('\\t\\tA'), 'raw literal must preserve leading tabs: ${r.output}'
	assert r.output.contains('\\t\\tB'), 'raw literal must preserve leading tabs: ${r.output}'
}

fn test_plain_triple_still_dedents() {
	// plain ''' → dedent strips the leading blank line + common `\t\t` indent.
	r := run_rl("[?str '''\n\t\tA\n\t\tB''']")
	assert r.exit_code == 0, 'errored: ${r.output}'
	assert !r.output.contains('\\t\\tA'), 'plain triple must dedent (no leading tabs): ${r.output}'
	assert r.output.contains('A'), 'dedented content present: ${r.output}'
}

fn test_raw_double_quote() {
	r := run_rl('[?str r"""\n\tX"""]')
	assert r.exit_code == 0, 'errored: ${r.output}'
	assert r.output.contains('\\tX'), 'r""" must preserve the leading tab: ${r.output}'
}

fn test_bare_r_identifier_unaffected() {
	// `r` is only a raw-string prefix immediately before a triple quote; a bare
	// binding named `r` must still be an ordinary identifier.
	r := run_rl('[?let [= $r 5] [+ $r 1]]')
	assert r.exit_code == 0, 'errored: ${r.output}'
	assert r.output.trim_space() == '6', 'bare ident r broke: ${r.output}'
}

fn test_raw_hole_in_str_directive() {
	// r''' composes with [?str] interpolation (#66 holes) — the raw body is the
	// template, computed holes still evaluate.
	r := run_rl("[?let [= \$n 2] [?str r'''v={[* \$n 3]}''']]")
	assert r.exit_code == 0, 'errored: ${r.output}'
	assert r.output.contains('v=6'), 'raw template with computed hole failed: ${r.output}'
}

// ── source: vcx/tests/temporal_lex_test.v ──
// v08_temporal_lex_test — cluster 1 (LEXER/DATETIME) of the parser-parity
// convergence. The PROGRAM parser (code.parse) must lex `2024-01-15` as ONE
// date token and `…T..Z` as ONE datetime token per lexicon §9 [L23]/[L24],
// instead of shattering into `2024 -1 -15` / rejecting. Convergence target is
// cx.parse (the spec-faithful side): both must render identically through
// code.render_canonical.

fn code_canon(src string) string {
	n := code.program_parse_to_typed_node(src) or { return 'REJECT' }
	return code.render_canonical(n)
}

fn cx_canon(src string) string {
	doc := cx.parse(src) or { return 'REJECT: ${err}' }
	if doc.elements.len != 1 {
		return 'REJECT: ${doc.elements.len} elements'
	}
	return code.render_canonical(doc.elements[0])
}

fn test_single_date_token() {
	// Date is one token → date scalar, NOT 2024 -1 -15. It renders BARE — a bare
	// `2024-01-15` re-auto-types to a date on round-trip, whereas a quoted form
	// would re-parse as a string and lose the date type (@CHOICE-1 slice A: the
	// program renderer now emits date/datetime body items unquoted, matching the
	// data parser and the bijection invariant).
	assert code_canon('[d 2024-01-15]') == '[d 2024-01-15]'
}

fn test_single_datetime_token() {
	assert code_canon('[dt 2024-01-15T10:30:00Z]') == '[dt 2024-01-15T10:30:00Z]'
}

fn test_datetime_with_offset() {
	assert code_canon('[dt 2024-01-15T10:30:00+05:30]') == '[dt 2024-01-15T10:30:00+05:30]'
}

fn test_datetime_fractional() {
	assert code_canon('[dt 2024-01-15T10:30:00.250Z]') == '[dt 2024-01-15T10:30:00.250Z]'
}

fn test_date_parity_with_cx() {
	assert code_canon('[d 2024-01-15]') == cx_canon('[d 2024-01-15]')
	assert code_canon('[dt 2024-01-15T10:30:00Z]') == cx_canon('[dt 2024-01-15T10:30:00Z]')
}

fn test_plain_int_year_unaffected() {
	// A bare year (no -MM-DD) is still a plain int.
	assert code_canon('[n 2024]') == '[n 2024]'
}

fn test_minus_arithmetic_unaffected() {
	// `[- $a $b]` arithmetic head must not be disturbed by temporal lexing.
	got := code.eval_code('[doc]', '[?let [= $a 10] [= $b 3] [- $a $b]]', 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert got == '7', 'got ${got}'
}

fn test_negative_number_unaffected() {
	assert code_canon('[n -7]') == '[n -7]'
}

// ── source: vcx/tests/triple_quoted_test.v ──
// Triple-quoted lookahead-on-close (v0.8.0) — a triple-quoted string
// closes at the LAST `'''` (or `"""`) within any maximal run of the
// delimiter character. Operationally: when the scanner sees the
// triple-delimiter, it peeks one byte further; if that byte is the
// same delimiter, the matched triple is treated as content and the
// scanner advances ONE byte rather than three. This makes content
// containing trailing delimiters expressible without escapes (which
// triple-quoted forms otherwise lack).
//
// Symmetric for `'''…'''` and `"""…"""`. The double-quote variant is
// new in v0.8.0 — the data parser previously had no `"""` reading
// path, which forced the doc scaffolder (scripts/gen_docs/scaffold.sh)
// to post-process `cx eval` output via a Python band-aid.

fn scalar_value(doc cx.Document) string {
	if doc.elements.len == 0 { return '' }
	n := doc.elements[0]
	if n is cx.ScalarNode {
		v := n.value
		if v is string { return v }
	}
	if n is cx.TextNode { return n.value }
	return ''
}

// ── Triple-single-quote — existing form (regression checks) ─────────────────

fn test_triple_single_basic() {
	doc := cx.parse("'''hello'''") or { panic(err) }
	assert scalar_value(doc) == 'hello'
}

fn test_triple_single_one_trailing_quote() {
	// '''hello'''' → content `hello'` (one trailing single-quote
	// absorbed via lookahead-on-close).
	doc := cx.parse("'''hello''''") or { panic(err) }
	assert scalar_value(doc) == "hello'"
}

fn test_triple_single_two_trailing_quotes() {
	doc := cx.parse("'''hello'''''") or { panic(err) }
	assert scalar_value(doc) == "hello''"
}

fn test_triple_single_three_trailing_quotes() {
	doc := cx.parse("'''hello''''''") or { panic(err) }
	assert scalar_value(doc) == "hello'''"
}

// ── Triple-double-quote — new in v0.8.0 ─────────────────────────────────────

fn test_triple_double_basic() {
	doc := cx.parse('"""hello"""') or { panic(err) }
	assert scalar_value(doc) == 'hello'
}

fn test_triple_double_one_trailing_quote() {
	// """hello"""" → content `hello"` (the band-aid case — emitted by
	// vcx/code/render.v::choose_render_quote when content has both `'`
	// and `"` but no `"""` and ends with `"`).
	doc := cx.parse('"""hello""""') or { panic(err) }
	assert scalar_value(doc) == 'hello"'
}

fn test_triple_double_two_trailing_quotes() {
	doc := cx.parse('"""hello"""""') or { panic(err) }
	assert scalar_value(doc) == 'hello""'
}

// ── Round-trip through the code-render emitter ──────────────────────────────

fn test_render_quote_roundtrip_band_aid_case() {
	// The exact shape that broke `make docs` before the parser fix: a
	// string containing both `'` and `"` whose last byte is `"`. The
	// emitter picks `"""…"""`, producing `"""…""""` (4 consecutive
	// `"`s at end). The parser must re-read content losslessly.
	original := 'A ::= "x\'y" "z"'
	src := '[code src=\'\'\'${original}\'\'\']'
	doc := cx.parse(src) or { panic(err) }
	mut got := ''
	if doc.elements.len > 0 {
		n := doc.elements[0]
		if n is cx.Element {
			for a in n.attrs {
				if a.name == 'src' {
					v := a.value
					if v is string { got = v }
				}
			}
		}
	}
	assert got == original
}

// ── source: vcx/tests/underscore_name_test.v ──
// v08_underscore_name_test — cluster 5 (NAME-RULE) of the parser-parity
// convergence. This is the ONE cluster where code.parse is spec-faithful and
// cx.parse is the bug: [6] NameStartChar INCLUDES `_`, so `_private` is a
// valid element name. cx.parse historically rejected `_`-leading heads
// (routing them to the `[__ …]` markdown-underline shorthand). Fix: only the
// double-underscore form `[__ body]` is the underline shorthand; everything
// else is a regular element name.

fn cx_render(src string) string {
	doc := cx.parse(src) or { return 'REJECT: ${err}' }
	if doc.elements.len != 1 {
		return 'REJECT: ${doc.elements.len} elements'
	}
	return code.render_canonical(doc.elements[0])
}

fn test_underscore_leading_name_accepted() {
	assert cx_render('[_private 1]') == '[_private 1]'
}

fn test_bare_underscore_name() {
	assert cx_render('[_ 1]') == '[_ 1]'
}

fn test_underscore_name_with_children() {
	assert cx_render('[_internal [_field 2]]') == '[_internal [_field 2]]'
}

fn test_double_underscore_is_plain_element() {
	// D-B (markdown removed): the former `[__ body]` underline shorthand is
	// gone. `__` is an ordinary element name ([6] NameStartChar includes `_`),
	// so `[__ hello]` is the element `__` with text child `hello` — no <u>.
	doc := cx.parse('[__ hello]') or {
		assert false, 'parse failed: ${err}'
		return
	}
	assert doc.elements.len == 1
	el := doc.elements[0]
	if el is cx.Element {
		assert el.name == '__', 'expected element __, got ${el.name}'
	} else {
		assert false, 'expected Element'
	}
}

fn test_underscore_parity_with_code() {
	cx_out := cx_render('[_private 1]')
	n := code.program_parse_to_typed_node('[_private 1]') or {
		assert false, 'code parse failed: ${err}'
		return
	}
	code_out := code.render_canonical(n)
	assert cx_out == code_out, 'cx=${cx_out} code=${code_out}'
}

// ── source: vcx/tests/type_expr_test.v ──
// Tests for the Phase 2.16 structural TypeExpr AST (vcx/cx/type_expr.v).
//
// Covers:
//   - parse_type_expr for every kind name, element names, `[or …]`
